use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;
use crate::aap::caps::tool_llm::Reply;

struct Node;

/// Bound on the tool-orchestration loop, so a model that keeps asking for
/// lookups can never make the node spin forever.
const MAX_ROUNDS: usize = 4;

/// Defensive echo of the graph contract `requires len(question) <= 512`.
/// The host checks `requires` on every input; we treat an over-long question
/// as a boundary violation and refuse rather than forward it to the model.
const MAX_QUESTION_LEN: usize = 512;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > MAX_QUESTION_LEN {
            return ResponseResult::Error(LlmError {
                message: "question exceeds the contract bound of 512".to_string(),
            });
        }

        let system = "You are a customer-support agent. Answer the user's \
                      question using the provided knowledge. When you need \
                      more information, ask for the `lookup` tool; otherwise \
                      reply with the final answer text.";

        let mut prompt = build_prompt(&ctx);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    // The only tool in this node's scope is `lookup`, backed
                    // by the read-only knowledge-base handle. A request for
                    // anything else is out of scope and cannot be served.
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        append_lookup(&mut prompt, &req.query, &results);
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!("requested tool not in scope: {}", req.tool),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within the round limit"
                .to_string(),
        })
    }
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\nQuestion: ");
    p.push_str(&ctx.question);
    if !ctx.knowledge.is_empty() {
        p.push_str("\n\nKnown context:\n");
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }
    p
}

fn append_lookup(prompt: &mut String, query: &str, results: &[String]) {
    prompt.push_str("\n\n[tool:lookup] query: ");
    prompt.push_str(query);
    prompt.push('\n');
    if results.is_empty() {
        prompt.push_str("(no results)\n");
    } else {
        for r in results {
            prompt.push_str("- ");
            prompt.push_str(r);
            prompt.push('\n');
        }
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
```

